class Solution { public: vector<int> smallestDiff(vector<int>& a, vector<int>& b, vector<int>& c) { sort(a.begin(), a.end()); sort(b.begin(), b.end()); sort(c.begin(), c.end()); int n = a.size(), m = b.size(), p = c.size(); int i = 0, j = 0, k = 0; int minDiff = 2147483647; int minSum = 2147483647; vector<int> res; while (i < n && j < m && k < p) { int mn = min({a[i], b[j], c[k]}); int mx = max({a[i], b[j], c[k]}); int diff = mx - mn; int sum = a[i] + b[j] + c[k]; if (diff < minDiff) { minDiff = diff; minSum = sum; res = {a[i], b[j], c[k]}; } else if (diff == minDiff) { if (sum < minSum) { minSum = sum; res = {a[i], b[j], c[k]}; } } if (a[i] == mn) i++; else if (b[j] == mn) j++; else k++; } sort(res.rbegin(), res.rend()); return res; } };